    const mast = $("#masthead");
    const setMast = () => root.style.setProperty("--mast-h", mast.offsetHeight + "px");
    if (window.ResizeObserver) { const ro = new ResizeObserver(setMast); ro.observe(mast); cleanups.push(() => ro.disconnect()); }
    setMast();
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const restyle = () => { styleBase(); renderMap(); };
    if (mq.addEventListener) { mq.addEventListener("change", restyle); cleanups.push(() => mq.removeEventListener("change", restyle)); }
    const mo = new MutationObserver(restyle);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
    cleanups.push(() => mo.disconnect());
